"""Automatic Restart Sign-On (ARSO) / Trusted Boot Auto-Logon (TBAL) secret parsing.

The LSA secret ``M$_MSV1_0_TBAL_PRIMARY_{GUID}`` stashes the signed-in account's
credentials so Windows can log the account back on after an update reboot. The payload
carries the account's NT hash, its SHA-1 password hash and the user name. Recovering it
needs only the boot key (the secret decrypts like any other LSA secret); the SHA-1 hash
then opens that account's DPAPI master keys without the password.

The field layout was read from a real TBAL secret and confirmed field by field: the NT
hash equals MD4 of the account password, the SHA-1 hash opens the account's master keys,
and the trailing printable field is the user name. It is validated on one image; treat
the offsets as that single observation.
"""
import re
import struct

_ZERO16 = b'\x00' * 16
_ZERO20 = b'\x00' * 20
_TEXT_RUN = re.compile(rb'(?:[\x20-\x7e]\x00){2,}')


def parse_tbal(data):
    """``{username, nt_hash, lm_hash, sha1_hash}`` from a decrypted TBAL secret, or None.

    Hashes stored as all zeros (absent) come back as ``None``. Returns ``None`` when the
    payload is too short or its size field does not match its length.
    """
    if len(data) < 68 or struct.unpack('<L', data[4:8])[0] != len(data):
        return None
    nt = data[16:32]
    lm = data[32:48]
    sha1 = data[48:68]
    runs = _TEXT_RUN.findall(data[68:])
    username = runs[-1].decode('utf-16-le') if runs else ''
    return {
        'username': username,
        'nt_hash': None if nt == _ZERO16 else nt,
        'lm_hash': None if lm == _ZERO16 else lm,
        'sha1_hash': None if sha1 == _ZERO20 else sha1,
    }
